// TreeMap: always alphabetically sorted by key
Map<String,Integer> sorted = new TreeMap<>();
sorted.put("Thunder",90); sorted.put("Arc",20); sorted.put("Frost",60);
sorted.forEach((k,v) -> System.out.println(k + ": " + v));
// Arc: 20 / Frost: 60 / Thunder: 90

