System.out.println(castHistory.pop()); // Shield
System.out.println(castHistory.pop()); // Fireball

PriorityQueue<Integer> urgency = new PriorityQueue<>();
urgency.offer(5); urgency.offer(1); urgency.offer(3);
// Always handles the most urgent (smallest) first:
while (!urgency.isEmpty()) {
    System.out.print(urgency.poll() + " "); // 1 3 5
}

